static void selectSort(int a[], int n, int *swaps)
{
    int i, j, k;
    *swaps = 0;
    for (i = 0; i < n - 1; i++) {
        k = i;
        for (j = i + 1; j < n; j++)
            if (a[j] < a[k]) k = j;
